insert into public.course_lessons(id,ordinal,data) values ('look-before-copy',0,'{"id":"look-before-copy","chapter":1,"title":"Look before you copy","topic":"Copying the Opponent","pages":"3–4","story":"Seirawan recalls copying his opponent instead of examining the position. Replaying the game reveals a free bishop that he missed. Before following a plan, check what the last move changed.","moves":["d3","d5","d4","e5","e4","Bg4"],"fen":"rn1qkbnr/ppp2ppp/8/3pp3/3PP1b1/8/PPP2PPP/RNBQKBNR w KQkq - 1 4","prompt":"White to move. Win the unprotected bishop.","hints":["Look for a capture before copying a move.","The queen has an open diagonal from d1."],"answers":[["Qxg4"]],"explanation":"Qxg4 wins the bishop on g4. The diagonal d1–e2–f3–g4 is clear. Checking available captures is more useful than automatically copying an opponent.","question":"What should you do after your opponent moves?","choices":["Check threats and available captures","Copy the move immediately","Always move your queen"],"correct":0,"replies":[],"steps":[{"d4e5":{"good":false,"san":"dxe5","fen":"rn1qkbnr/ppp2ppp/8/3pP3/4P1b1/8/PPP2PPP/RNBQKBNR b KQkq - 0 4","reply":null},"e4d5":{"good":false,"san":"exd5","fen":"rn1qkbnr/ppp2ppp/8/3Pp3/3P2b1/8/PPP2PPP/RNBQKBNR b KQkq - 0 4","reply":null},"a2a3":{"good":false,"san":"a3","fen":"rn1qkbnr/ppp2ppp/8/3pp3/3PP1b1/P7/1PP2PPP/RNBQKBNR b KQkq - 0 4","reply":null},"a2a4":{"good":false,"san":"a4","fen":"rn1qkbnr/ppp2ppp/8/3pp3/P2PP1b1/8/1PP2PPP/RNBQKBNR b KQkq - 0 4","reply":null},"b2b3":{"good":false,"san":"b3","fen":"rn1qkbnr/ppp2ppp/8/3pp3/3PP1b1/1P6/P1P2PPP/RNBQKBNR b KQkq - 0 4","reply":null},"b2b4":{"good":false,"san":"b4","fen":"rn1qkbnr/ppp2ppp/8/3pp3/1P1PP1b1/8/P1P2PPP/RNBQKBNR b KQkq - 0 4","reply":null},"c2c3":{"good":false,"san":"c3","fen":"rn1qkbnr/ppp2ppp/8/3pp3/3PP1b1/2P5/PP3PPP/RNBQKBNR b KQkq - 0 4","reply":null},"c2c4":{"good":false,"san":"c4","fen":"rn1qkbnr/ppp2ppp/8/3pp3/2PPP1b1/8/PP3PPP/RNBQKBNR b KQkq - 0 4","reply":null},"f2f3":{"good":fals