insert into public.course_lessons(id,ordinal,data) values ('check-not-mate',1,'{"id":"check-not-mate","chapter":1,"title":"Check is not checkmate","topic":"Copying the Opponent","pages":"4","story":"The same childhood game ended with a mistaken claim of checkmate. The king was in check, but several legal blocks were available. An uncomfortable position is not automatically a lost game.","moves":["d3","d5","d4","e5","e4","Bg4","dxe5","Bb4+"],"fen":"rn1qk1nr/ppp2ppp/8/3pP3/1b2P1b1/8/PPP2PPP/RNBQKBNR w KQkq - 1 5","prompt":"White is in check. Block the bishop’s attack.","hints":["Check the diagonal from b4 to e1.","A piece or pawn can block on c3 or d2."],"answers":[["c3"],["Nc3"],["Nd2"],["Bd2"],["Qd2"]],"explanation":"You stopped the check. White still has serious problems, including an exposed queen, but this position was not checkmate. Checkmate requires there to be no legal escape.","question":"When is a checked king checkmated?","choices":["Whenever it cannot move itself","When no legal move removes the check","When the queen is threatened"],"correct":1,"replies":[],"steps":[{"c2c3":{"good":true,"san":"c3","fen":"rn1qk1nr/ppp2ppp/8/3pP3/1b2P1b1/2P5/PP3PPP/RNBQKBNR b KQkq - 0 5","reply":null},"b1c3":{"good":true,"san":"Nc3","fen":"rn1qk1nr/ppp2ppp/8/3pP3/1b2P1b1/2N5/PPP2PPP/R1BQKBNR b KQkq - 2 5","reply":null},"b1d2":{"good":true,"san":"Nd2","fen":"rn1qk1nr/ppp2ppp/8/3pP3/1b2P1b1/8/PPPN1PPP/R1BQKBNR b KQkq - 2 5","reply":null},"c1d2":{"good":true,"san":"Bd2","fen":"rn1qk1nr/ppp2ppp/8/3pP3/1b2P1b1/8/PPPB1PPP/RN1QKBNR b KQkq - 2 5","reply":null},"d1d2":{"good":true,"san":"Qd2","fen":"rn1qk1nr/ppp2ppp/8/3pP3/1b2P1b1/8/PPPQ1PPP/RNB1KBNR b KQkq - 2 5","reply":null}}]}'::jsonb) on conflict(id) do update set ordinal=excluded.ordinal,data=excluded.data;
insert into public.course_lessons(id,ordinal,data) values ('cannon-fire',2,'{"id":"cannon-fire","chapter":1,"title":"Keep the rooks safe","topic":"Cannon Fire","pages":"5–7","story":"Seirawan imagined his rooks as cannons and brought them out before his other pieces. A bishop captured a rook. Even after a mistake, examine the position for the best recovery.","moves":["h4","d5","Rh3","Bxh3"],"fen":"rn1qkbnr/ppp1pppp/8/3p4/7P/7b/PPPPPPP1/RNBQKBN1 w Qkq - 0 3","prompt":"White has lost a rook. Capture the bishop in return.","hints":["Do not ignore a capture just because your plan went wrong.","The knight on g1 can recapture."],"answers":[["Nxh3"]],"explanation":"Nxh3 recovers the bishop. It does not undo the rook loss, but it limits the damage. Early rook adventures can expose valuable pieces before the rest of the army is ready.","question":"What is the useful response when your plan fails?","choices":["Continue it regardless","Stop checking threats","Reassess and limit the damage"],"correct":2,"replies":[],"steps":[{"h4h5":{"good":false,"san":"h5","fen":"rn1qkbnr/ppp1pppp/8/3p3P/8/7b/PPPPPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"a2a3":{"good":false,"san":"a3","fen":"rn1qkbnr/ppp1pppp/8/3p4/7P/P6b/1PPPPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"a2a4":{"good":false,"san":"a4","fen":"rn1qkbnr/ppp1pppp/8/3p4/P6P/7b/1PPPPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"b2b3":{"good":false,"san":"b3","fen":"rn1qkbnr/ppp1pppp/8/3p4/7P/1P5b/P1PPPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"b2b4":{"good":false,"san":"b4","fen":"rn1qkbnr/ppp1pppp/8/3p4/1P5P/7b/P1PPPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"c2c3":{"good":false,"san":"c3","fen":"rn1qkbnr/ppp1pppp/8/3p4/7P/2P4b/PP1PPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"c2c4":{"good":false,"san":"c4","fen":"rn1qkbnr/ppp1pppp/8/3p4/2P4P/7b/PP1PPPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"d2d3":{"good":false,"san":"d3","fen":"rn1qkbnr/ppp1pppp/8/3p4/7P/3P3b/PPP1PPP1/RNBQKBN1 b Qkq - 0 3","reply":null},"d2d4":{"good":false,"san":"d4","fen":"rn1qkbn