insert into public.course_lessons(id,ordinal,data) values ('queen-tempo',3,'{"id":"queen-tempo","chapter":1,"title":"Develop with a threat","topic":"Queen Raid","pages":"13","story":"After an early queen capture in the Scandinavian Defense, White can develop a knight while attacking the queen. This gains time for development. Early queen moves are not always wrong; their cost depends on the position.","moves":["e4","d5","exd5","Qxd5"],"fen":"rnb1kbnr/ppp1pppp/8/3q4/8/8/PPPP1PPP/RNBQKBNR w KQkq - 0 3","prompt":"Develop a knight and attack the black queen.","hints":["Can one move do two useful jobs?","The knight on b1 can reach c3."],"answers":[["Nc3"]],"explanation":"Nc3 develops a knight, influences the centre and attacks the queen on d5. Black must respond to the threat while White brings another piece into play.","question":"What does developing with tempo mean here?","choices":["Developing while making a threat","Moving as fast as possible","Always giving check"],"correct":0,"replies":[],"steps":[{"a2a3":{"good":false,"san":"a3","fen":"rnb1kbnr/ppp1pppp/8/3q4/8/P7/1PPP1PPP/RNBQKBNR b KQkq - 0 3","reply":null},"a2a4":{"good":false,"san":"a4","fen":"rnb1kbnr/ppp1pppp/8/3q4/P7/8/1PPP1PPP/RNBQKBNR b KQkq - 0 3","reply":null},"b2b3":{"good":false,"san":"b3","fen":"rnb1kbnr/ppp1pppp/8/3q4/8/1P6/P1PP1PPP/RNBQKBNR b KQkq - 0 3","reply":null},"b2b4":{"good":false,"san":"b4","fen":"rnb1kbnr/ppp1pppp/8/3q4/1P6/8/P1PP1PPP/RNBQKBNR b KQkq - 0 3","reply":null},"c2c3":{"good":false,"san":"c3","fen":"rnb1kbnr/ppp1pppp/8/3q4/8/2P5/PP1P1PPP/RNBQKBNR b KQkq - 0 3","reply":null},"c2c4":{"good":false,"san":"c4","fen":"rnb1kbnr/ppp1pppp/8/3q4/2P5/8/PP1P1PPP/RNBQKBNR b KQkq - 0 3","reply":null},"d2d3":{"good":false,"san":"d3","fen":"rnb1kbnr/ppp1pppp/8/3q4/8/3P4/PPP2PPP/RNBQKBNR b KQkq - 0 3","reply":null},"d2d4":{"good":false,"san":"d4","fen":"rnb1kbnr/ppp1pppp/8/3q4/3P4/8/PPP2PPP/RNBQKBNR b KQkq - 0 3","reply":null},"f2f3":{"good":false,"san":"f3","fen":"rnb1kbnr/ppp1pppp/8/3q4/8/5P2