insert into public.course_lessons(id,ordinal,data) values ('stop-raid',4,'{"id":"stop-raid","chapter":1,"title":"Meet the queen raid","topic":"Destroying the Queen Raid","pages":"16","story":"A queen and bishop aimed at f7 can threaten a quick mate. In the book’s example, Black first defends the e5-pawn, then blocks the mating threat while attacking the queen.","moves":["e4","e5","Qh5","Nc6","Bc4"],"fen":"r1bqkbnr/pppp1ppp/2n5/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR b KQkq - 3 3","prompt":"Black to move. Block the queen’s path to f7 and attack her.","hints":["The black knight already protects e5.","A pawn can move from g7 to g6."],"answers":[["g6"]],"explanation":"g6 blocks the queen’s diagonal to f7 and attacks the queen on h5. In this position e5 is defended by the c6-knight; that detail matters.","question":"Why does the position matter before pushing the g-pawn?","choices":["Pawn moves always win time","Other threats, including e5, must be covered","Queens cannot capture pawns"],"correct":1,"replies":[],"steps":[{"a8b8":{"good":false,"san":"Rb8","fen":"1rbqkbnr/pppp1ppp/2n5/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQk - 4 4","reply":null},"d8e7":{"good":false,"san":"Qe7","fen":"r1b1kbnr/ppppqppp/2n5/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4","reply":null},"d8f6":{"good":false,"san":"Qf6","fen":"r1b1kbnr/pppp1ppp/2n2q2/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4","reply":null},"d8g5":{"good":false,"san":"Qg5","fen":"r1b1kbnr/pppp1ppp/2n5/4p1qQ/2B1P3/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4","reply":null},"d8h4":{"good":false,"san":"Qh4","fen":"r1b1kbnr/pppp1ppp/2n5/4p2Q/2B1P2q/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4","reply":null},"e8e7":{"good":false,"san":"Ke7","fen":"r1bq1bnr/ppppkppp/2n5/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQ - 4 4","reply":null},"f8e7":{"good":false,"san":"Be7","fen":"r1bqk1nr/ppppbppp/2n5/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4","reply":null},"f8d6":{"good":false,"san":"Bd6","fen":"r1bqk1nr/pppp1ppp/2nb4/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4","reply":null},"f8c5"