insert into public.course_lessons(id,ordinal,data) values ('coordinate-defence',5,'{"id":"coordinate-defence","chapter":1,"title":"Bring another defender","topic":"Destroying the Queen Raid","pages":"16–20","story":"The raiding queen renews the threat from f3. Black calmly develops another minor piece. Coordinated development can make a queen attack lose time.","moves":["e4","e5","Qh5","Nc6","Bc4","g6","Qf3"],"fen":"r1bqkbnr/pppp1p1p/2n3p1/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR b KQkq - 1 4","prompt":"Black to move. Develop a knight to block the attack on f7.","hints":["Find the line between f3 and f7.","The g8-knight can move to f6."],"answers":[["Nf6"]],"explanation":"Nf6 blocks the queen’s line to f7 and brings another defender into play. Black has developed both knights while White has spent several turns moving the queen.","question":"What makes this defence useful?","choices":["It develops a piece and answers the threat","It ignores the opponent","It wins the queen immediately"],"correct":0,"replies":[],"steps":[{"a8b8":{"good":false,"san":"Rb8","fen":"1rbqkbnr/pppp1p1p/2n3p1/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQk - 2 5","reply":null},"d8e7":{"good":false,"san":"Qe7","fen":"r1b1kbnr/ppppqp1p/2n3p1/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 2 5","reply":null},"d8f6":{"good":false,"san":"Qf6","fen":"r1b1kbnr/pppp1p1p/2n2qp1/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 2 5","reply":null},"d8g5":{"good":false,"san":"Qg5","fen":"r1b1kbnr/pppp1p1p/2n3p1/4p1q1/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 2 5","reply":null},"d8h4":{"good":false,"san":"Qh4","fen":"r1b1kbnr/pppp1p1p/2n3p1/4p3/2B1P2q/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 2 5","reply":null},"e8e7":{"good":false,"san":"Ke7","fen":"r1bq1bnr/ppppkp1p/2n3p1/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQ - 2 5","reply":null},"f8g7":{"good":false,"san":"Bg7","fen":"r1bqk1nr/pppp1pbp/2n3p1/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 2 5","reply":null},"f8h6":{"good":false,"san":"Bh6","fen":"r1bqk1nr/pppp1p1p/2n3pb/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq 