insert into public.course_lessons(id,ordinal,data) values ('central-start',6,'{"id":"central-start","chapter":2,"title":"Make room in the centre","topic":"Basic Opening Principles","pages":"25–27","story":"Chapter 2 puts pawns and minor pieces at the heart of opening play. A central pawn move can claim space and open lines for development. The four central squares are d4, e4, d5 and e5.","moves":[],"fen":"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1","prompt":"White to move. Advance a central pawn two squares.","hints":["Choose the d-pawn or e-pawn.","Either d4 or e4 meets this lesson’s goal."],"answers":[["e4"],["d4"]],"explanation":"Both e4 and d4 occupy a central square and release a bishop. These are useful beginnings, not a promise of an advantage by themselves.","question":"Which group contains the four central squares?","choices":["a1, a8, h1, h8","c1, f1, c8, f8","d4, e4, d5, e5"],"correct":2,"replies":[],"steps":[{"a2a3":{"good":false,"san":"a3","fen":"rnbqkbnr/pppppppp/8/8/8/P7/1PPPPPPP/RNBQKBNR b KQkq - 0 1","reply":null},"a2a4":{"good":false,"san":"a4","fen":"rnbqkbnr/pppppppp/8/8/P7/8/1PPPPPPP/RNBQKBNR b KQkq - 0 1","reply":null},"b2b3":{"good":false,"san":"b3","fen":"rnbqkbnr/pppppppp/8/8/8/1P6/P1PPPPPP/RNBQKBNR b KQkq - 0 1","reply":null},"b2b4":{"good":false,"san":"b4","fen":"rnbqkbnr/pppppppp/8/8/1P6/8/P1PPPPPP/RNBQKBNR b KQkq - 0 1","reply":null},"c2c3":{"good":false,"san":"c3","fen":"rnbqkbnr/pppppppp/8/8/8/2P5/PP1PPPPP/RNBQKBNR b KQkq - 0 1","reply":null},"c2c4":{"good":false,"san":"c4","fen":"rnbqkbnr/pppppppp/8/8/2P5/8/PP1PPPPP/RNBQKBNR b KQkq - 0 1","reply":null},"d2d3":{"good":false,"san":"d3","fen":"rnbqkbnr/pppppppp/8/8/8/3P4/PPP1PPPP/RNBQKBNR b KQkq - 0 1","reply":null},"d2d4":{"good":true,"san":"d4","fen":"rnbqkbnr/pppppppp/8/8/3P4/8/PPP1PPPP/RNBQKBNR b KQkq - 0 1","reply":null},"e2e3":{"good":false,"san":"e3","fen":"rnbqkbnr/pppppppp/8/8/8/4P3/PPPP1PPP/RNBQKBNR b KQkq - 0 1","reply":null},"e2e4":{"good":true,"san":"e4","fen":