insert into public.course_lessons(id,ordinal,data) values ('develop-purpose',7,'{"id":"develop-purpose","chapter":2,"title":"Develop with purpose","topic":"Basic Opening Principles","pages":"25–29","story":"The book describes learning to bring knights and bishops into the game before launching queen or rook adventures. Choose useful squares, watch threats, and coordinate your pieces.","moves":["e4","e5"],"fen":"rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2","prompt":"White to move. Develop a knight toward the centre.","hints":["Both knights have useful central developing squares.","Nf3 attacks e5; Nc3 supports e4 and controls d5."],"answers":[["Nf3"],["Nc3"]],"explanation":"Nf3 and Nc3 both develop a knight toward useful central squares. Nf3 also attacks the e5-pawn; Nc3 supports e4 and influences d5. Different good moves can serve the same principle.","question":"Which pieces usually take priority in opening development?","choices":["The queen and rooks","Knights and bishops","Only the king"],"correct":1,"replies":[],"steps":[{"a2a3":{"good":false,"san":"a3","fen":"rnbqkbnr/pppp1ppp/8/4p3/4P3/P7/1PPP1PPP/RNBQKBNR b KQkq - 0 2","reply":null},"a2a4":{"good":false,"san":"a4","fen":"rnbqkbnr/pppp1ppp/8/4p3/P3P3/8/1PPP1PPP/RNBQKBNR b KQkq - 0 2","reply":null},"b2b3":{"good":false,"san":"b3","fen":"rnbqkbnr/pppp1ppp/8/4p3/4P3/1P6/P1PP1PPP/RNBQKBNR b KQkq - 0 2","reply":null},"b2b4":{"good":false,"san":"b4","fen":"rnbqkbnr/pppp1ppp/8/4p3/1P2P3/8/P1PP1PPP/RNBQKBNR b KQkq - 0 2","reply":null},"c2c3":{"good":false,"san":"c3","fen":"rnbqkbnr/pppp1ppp/8/4p3/4P3/2P5/PP1P1PPP/RNBQKBNR b KQkq - 0 2","reply":null},"c2c4":{"good":false,"san":"c4","fen":"rnbqkbnr/pppp1ppp/8/4p3/2P1P3/8/PP1P1PPP/RNBQKBNR b KQkq - 0 2","reply":null},"d2d3":{"good":false,"san":"d3","fen":"rnbqkbnr/pppp1ppp/8/4p3/4P3/3P4/PPP2PPP/RNBQKBNR b KQkq - 0 2","reply":null},"d2d4":{"good":false,"san":"d4","fen":"rnbqkbnr/pppp1ppp/8/4p3/3PP3/8/PPP2PPP/RNBQKBNR b KQkq - 0 2","reply":null},"f2f3":{"g