insert into public.course_lessons(id,ordinal,data) values ('bishop-development',8,'{"id":"bishop-development","chapter":2,"title":"Give the bishop a job","topic":"Early Opening Influences","pages":"29","story":"In the illustrative game, White brings a bishop to c4, developing it while eyeing f7. Development is most useful when a piece helps a concrete plan.","moves":["e4","e5","Nf3","d6"],"fen":"rnbqkbnr/ppp2ppp/3p4/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 0 3","prompt":"Develop the f1-bishop to aim at f7.","hints":["Look along the diagonal leading to f7.","The bishop can move to c4."],"answers":[["Bc4"]],"explanation":"Bc4 places the bishop on an active diagonal toward f7 and clears f1. This is a development exercise, not a claim that Bc4 is the only good move.","question":"What makes c4 purposeful for this bishop?","choices":["It directly attacks the queen","It develops while pointing at f7","It guarantees a checkmate"],"correct":1,"replies":[],"steps":[{"f3d4":{"good":false,"san":"Nd4","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/3NP3/8/PPPP1PPP/RNBQKB1R b KQkq - 1 3","reply":null},"f3e5":{"good":false,"san":"Nxe5","fen":"rnbqkbnr/ppp2ppp/3p4/4N3/4P3/8/PPPP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"f3g5":{"good":false,"san":"Ng5","fen":"rnbqkbnr/ppp2ppp/3p4/4p1N1/4P3/8/PPPP1PPP/RNBQKB1R b KQkq - 1 3","reply":null},"f3h4":{"good":false,"san":"Nh4","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/4P2N/8/PPPP1PPP/RNBQKB1R b KQkq - 1 3","reply":null},"f3g1":{"good":false,"san":"Ng1","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 1 3","reply":null},"a2a3":{"good":false,"san":"a3","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/4P3/P4N2/1PPP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"a2a4":{"good":false,"san":"a4","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/P3P3/5N2/1PPP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"b2b3":{"good":false,"san":"b3","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/4P3/1P3N2/P1PP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"b2b4":{"good":false,"san":"b4","fen":"rnbqkbnr/ppp2ppp/3p4/4p3/1P2P3/5N2/P1PP1PPP/