insert into public.course_lessons(id,ordinal,data) values ('safe-king',9,'{"id":"safe-king","chapter":2,"title":"Give your king shelter","topic":"Basic Opening Principles","pages":"26","story":"The book’s opening goal is a safe king and a playable middlegame. This original practice position applies that principle: White has cleared the kingside and can castle legally.","moves":["e4","e5","Nf3","Nc6","Bc4","Bc5"],"fen":"r1bqk1nr/pppp1ppp/2n5/2b1p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 4 4","prompt":"White to move. Castle kingside to improve king safety.","hints":["Castling moves the king and rook together.","Select the king on e1, then g1."],"answers":[["O-O"]],"explanation":"Castling moves the king to g1 and rook to f1. Here the king is not in check, the path is clear and the king crosses no attacked square. Castling is not automatically safe in every position.","question":"Which condition prevents castling?","choices":["Your opponent has a queen","You have moved a pawn","Your king would cross an attacked square"],"correct":2,"replies":[],"steps":[{"c4b5":{"good":false,"san":"Bb5","fen":"r1bqk1nr/pppp1ppp/2n5/1Bb1p3/4P3/5N2/PPPP1PPP/RNBQK2R b KQkq - 5 4","reply":null},"c4a6":{"good":false,"san":"Ba6","fen":"r1bqk1nr/pppp1ppp/B1n5/2b1p3/4P3/5N2/PPPP1PPP/RNBQK2R b KQkq - 5 4","reply":null},"c4d5":{"good":false,"san":"Bd5","fen":"r1bqk1nr/pppp1ppp/2n5/2bBp3/4P3/5N2/PPPP1PPP/RNBQK2R b KQkq - 5 4","reply":null},"c4e6":{"good":false,"san":"Be6","fen":"r1bqk1nr/pppp1ppp/2n1B3/2b1p3/4P3/5N2/PPPP1PPP/RNBQK2R b KQkq - 5 4","reply":null},"c4f7":{"good":false,"san":"Bxf7+","fen":"r1bqk1nr/pppp1Bpp/2n5/2b1p3/4P3/5N2/PPPP1PPP/RNBQK2R b KQkq - 0 4","reply":null},"c4d3":{"good":false,"san":"Bd3","fen":"r1bqk1nr/pppp1ppp/2n5/2b1p3/4P3/3B1N2/PPPP1PPP/RNBQK2R b KQkq - 5 4","reply":null},"c4e2":{"good":false,"san":"Be2","fen":"r1bqk1nr/pppp1ppp/2n5/2b1p3/4P3/5N2/PPPPBPPP/RNBQK2R b KQkq - 5 4","reply":null},"c4f1":{"good":false,"san":"Bf1","fen":"r1bqk1nr/pppp1ppp/2n5/2b1p3/4P3/5N2/PPPP1P