insert into public.course_lessons(id,ordinal,data) values ('legall-combination',10,'{"id":"legall-combination","chapter":2,"title":"Pieces working together","topic":"Early Opening Influences","pages":"29–30","story":"In the book’s Legall’s Mate example, Black takes the queen and overlooks the coordinated minor pieces. The lesson is to calculate forcing moves rather than judge a position by material alone.","moves":["e4","e5","Nf3","d6","Bc4","Bg4","Nc3","h6","Nxe5","Bxd1"],"fen":"rn1qkbnr/ppp2pp1/3p3p/4N3/2B1P3/2N5/PPPP1PPP/R1BbK2R w KQkq - 0 6","prompt":"White to move. Find the forcing check, then finish the mate.","hints":["Look for a bishop check on f7.","After the king moves to e7, bring the c3-knight to d5."],"answers":[["Bxf7+","Nd5#"]],"explanation":"Bxf7+ forces Ke7, then Nd5 is checkmate. The bishops and knights cooperate to control the king’s escapes. This pattern works because of this exact arrangement of pieces.","question":"Why is losing the queen acceptable in this example?","choices":["The resulting attack forces checkmate","Queens are unimportant","Sacrifices always work"],"correct":0,"replies":["Ke7"],"steps":[{"e5c6":{"good":false,"san":"Nc6","fen":"rn1qkbnr/ppp2pp1/2Np3p/8/2B1P3/2N5/PPPP1PPP/R1BbK2R b KQkq - 1 6","reply":null},"e5d7":{"good":false,"san":"Nd7","fen":"rn1qkbnr/pppN1pp1/3p3p/8/2B1P3/2N5/PPPP1PPP/R1BbK2R b KQkq - 1 6","reply":null},"e5f7":{"good":false,"san":"Nxf7","fen":"rn1qkbnr/ppp2Np1/3p3p/8/2B1P3/2N5/PPPP1PPP/R1BbK2R b KQkq - 0 6","reply":null},"e5g6":{"good":false,"san":"Ng6","fen":"rn1qkbnr/ppp2pp1/3p2Np/8/2B1P3/2N5/PPPP1PPP/R1BbK2R b KQkq - 1 6","reply":null},"e5g4":{"good":false,"san":"Ng4","fen":"rn1qkbnr/ppp2pp1/3p3p/8/2B1P1N1/2N5/PPPP1PPP/R1BbK2R b KQkq - 1 6","reply":null},"e5f3":{"good":false,"san":"Nf3","fen":"rn1qkbnr/ppp2pp1/3p3p/8/2B1P3/2N2N2/PPPP1PPP/R1BbK2R b KQkq - 1 6","reply":null},"e5d3":{"good":false,"san":"Nd3","fen":"rn1qkbnr/ppp2pp1/3p3p/8/2B1P3/2NN4/PPPP1PPP/R1BbK2R b KQkq - 1 6","reply":null},"c4b5":{"goo