insert into public.course_lessons(id,ordinal,data) values ('review-grow',11,'{"id":"review-grow","chapter":2,"title":"Learn from the game","topic":"Introduction to Classical Openings","pages":"28–32","story":"Seirawan explains how recording games, analysing them and playing stronger opponents helped him improve. Review a familiar position and identify a useful move for yourself. The next step is to apply these principles in real games.","moves":["e4","e5","Nf3","Nc6"],"fen":"r1bqkbnr/pppp1ppp/2n5/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 2 3","prompt":"Develop your f1-bishop to an active square: c4 or b5.","hints":["Bring a new piece into play.","Bc4 aims at f7; Bb5 pressures the defender on c6."],"answers":[["Bc4"],["Bb5"]],"explanation":"Both moves develop a bishop with a purpose. Keep a record of your games and look for missed threats, lost development time and king-safety problems. Completing this course is a foundation, not a chess rating.","question":"What should you do after a difficult loss?","choices":["Review the moves and identify a lesson","Forget every move","Conclude that you cannot improve"],"correct":1,"replies":[],"steps":[{"f3d4":{"good":false,"san":"Nd4","fen":"r1bqkbnr/pppp1ppp/2n5/4p3/3NP3/8/PPPP1PPP/RNBQKB1R b KQkq - 3 3","reply":null},"f3e5":{"good":false,"san":"Nxe5","fen":"r1bqkbnr/pppp1ppp/2n5/4N3/4P3/8/PPPP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"f3g5":{"good":false,"san":"Ng5","fen":"r1bqkbnr/pppp1ppp/2n5/4p1N1/4P3/8/PPPP1PPP/RNBQKB1R b KQkq - 3 3","reply":null},"f3h4":{"good":false,"san":"Nh4","fen":"r1bqkbnr/pppp1ppp/2n5/4p3/4P2N/8/PPPP1PPP/RNBQKB1R b KQkq - 3 3","reply":null},"f3g1":{"good":false,"san":"Ng1","fen":"r1bqkbnr/pppp1ppp/2n5/4p3/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 3 3","reply":null},"a2a3":{"good":false,"san":"a3","fen":"r1bqkbnr/pppp1ppp/2n5/4p3/4P3/P4N2/1PPP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"a2a4":{"good":false,"san":"a4","fen":"r1bqkbnr/pppp1ppp/2n5/4p3/P3P3/5N2/1PPP1PPP/RNBQKB1R b KQkq - 0 3","reply":null},"b2b3":{"